    if exists(select 1 from public.guess_people where slug=p->>'slug') then continue; end if;
    select id into legacy from public.entities where lower(name)=lower(p->>'name') and mode='dem' limit 1;
    insert into public.guess_people(slug,name,aliases,legacy_entity_id)
      values(p->>'slug',p->>'name',array(select jsonb_array_elements_text(p->'aliases')),legacy) returning id into pid;
    insert into public.guess_person_facts(person_id,birth_year,gender,claims)
      values(pid,(p->>'birth_year')::smallint,p->>'gender',p->'claims');
    insert into public.guess_person_profiles(person_id,vocabulary_version,primary_lane,primary_speciality,known_for,specialities,clue,fairness_note)
      values(pid,2,p->>'primary_lane',p->>'primary_speciality',array(select jsonb_array_elements_text(p->'known_for')),
        array(select jsonb_array_elements_text(p->'specialities')),p->'clue'||jsonb_build_object('compatible_ids',jsonb_build_array(pid)),p->>'fairness_note');
  end loop;
end $$;
